package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec
var loanLines []string
var loanIndex int
var loanFile *os.File

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseImplied(s string, scale int32) decimal.Decimal {
	// s contains digits only (maybe spaces)
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// remove inner spaces if any
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// allow leading sign?
	neg := false
	if strings.HasPrefix(t, "-") {
		neg = true
		t = t[1:]
	} else if strings.HasPrefix(t, "+") {
		t = t[1:]
	}
	// digits only
	d := decimal.RequireFromString(t)
	if scale != 0 {
		d = d.Shift(-scale)
	}
	if neg {
		d = d.Neg()
	}
	return d
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	t = strings.ReplaceAll(t, " ", "")
	if t == "" {
		return 0
	}
	var v int64
	fmt.Sscan(t, &v)
	return v
}

func tenPow(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func storeDecimal(val decimal.Decimal, scale int32, intDigits int, doRound bool) decimal.Decimal {
	var q decimal.Decimal
	if doRound {
		q = val.Round(scale)
	} else {
		q = val.Truncate(scale)
	}
	// truncation of high-order digits: keep low-order digits that fit
	// total digits = intDigits + scale
	total := intDigits + int(scale)
	// compute scaled integer
	scaled := q.Shift(scale) // integer decimal
	// modulo base = 10^total
	modBase := tenPow(total)
	// for overflow, keep low-order digits: scaled mod modBase (preserving sign)
	if scaled.IsNegative() {
		abs := scaled.Abs()
		// check if abs >= modBase -> truncate
		if abs.GreaterThanOrEqual(modBase) {
			abs = abs.Mod(modBase)
		}
		scaled = abs.Neg()
		// COBOL keeps truncated value, need to handle negative overflow? just mod
	} else {
		if scaled.GreaterThanOrEqual(modBase) || scaled.Equal(modBase) {
			// use Mod; if scaled < modBase no change
			if scaled.GreaterThanOrEqual(modBase) {
				scaled = scaled.Mod(modBase)
			}
		} else if scaled.GreaterThanOrEqual(modBase) {
			scaled = scaled.Mod(modBase)
		}
		// also if scaled >= modBase
		if scaled.Cmp(modBase) >= 0 {
			scaled = scaled.Mod(modBase)
		}
	}
	// Alternative generic mod check: if abs >= modBase
	absScaled := scaled.Abs()
	if absScaled.Cmp(modBase) >= 0 {
		// already handled but ensure
		absScaled = absScaled.Mod(modBase)
		if scaled.IsNegative() {
			scaled = absScaled.Neg()
		} else {
			scaled = absScaled
		}
	}
	return scaled.Shift(-scale)
}

func formatEdited(val decimal.Decimal, picture string) string {
	// determine scale = number of '9'/'Z' after '.'
	dotPos := strings.Index(picture, ".")
	scale := 0
	intPattern := picture
	fracPattern := ""
	if dotPos >= 0 {
		intPattern = picture[:dotPos]
		fracPattern = picture[dotPos+1:]
		scale = len(fracPattern) // count of 9/Z (all 9 in these pics)
	}
	// count integer digits
	intDigits := 0
	for _, ch := range intPattern {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// get integer and fractional parts
	// val is expected to have at most scale decimals; ensure truncation/rounding already done
	// For formatting we just need integer part and fractional
	// Handle sign: assume non-negative; if negative, include minus? Not needed but handle.
	neg := val.IsNegative()
	if neg {
		val = val.Abs()
	}
	// integer part: truncate toward zero
	// get scaled integer
	scaled := val.Shift(int32(scale)).Truncate(0)
	// integer part
	intPart := scaled.Shift(-int32(scale)).Truncate(0)
	// fractional part as integer 0..10^scale-1
	// frac = scaled - intPart*10^scale
	pow10 := tenPow(scale)
	fIntDec := scaled.Sub(intPart.Mul(pow10))
	fracInt := fIntDec.IntPart()
	if fracInt < 0 {
		fracInt = -fracInt
	}
	intVal := intPart.IntPart()
	if intVal < 0 {
		intVal = -intVal
	}
	// overflow truncation for display: keep low-order intDigits digits
	if intDigits > 0 {
		modBase := int64(1)
		for i := 0; i < intDigits; i++ {
			modBase *= 10
		}
		// but intDigits up to 11, modBase fits 10^11
		if modBase > 0 {
			intVal = intVal % modBase
		}
	}
	// build integer string zero-padded to intDigits
	sInt := fmt.Sprintf("%0*d", intDigits, intVal)

	// build fractional string
	sFrac := ""
	if scale > 0 {
		sFrac = fmt.Sprintf("%0*d", scale, fracInt)
	}

	// Now map to pattern
	// integer section output length = len(intPattern)
	outInt := make([]rune, len(intPattern))
	digitIdx := 0
	// For comma suppression we need to know when non-zero seen
	nonZeroSeen := false
	// We need to know for each pattern position whether it's Z/9
	// To decide suppression of Z leading zeros, look at sInt digits
	// nonZeroSeen becomes true when we encounter a digit != '0'
	// But we must evaluate digit before deciding output char?
	for i, ch := range intPattern {
		if ch == ',' {
			if nonZeroSeen {
				outInt[i] = ','
			} else {
				outInt[i] = ' '
			}
		} else if ch == 'Z' || ch == '9' {
			d := sInt[digitIdx]
			digitIdx++
			if d != '0' {
				nonZeroSeen = true
			}
			if ch == 'Z' && d == '0' && !nonZeroSeen {
				// leading zero suppressed: but need to consider if all remaining digits are zero?
				// For suppression we already have nonZeroSeen false, so space
				// However need lookahead? In COBOL, a field of all zeros with Z's and final 9 prints 0 at 9.
				// Our logic: Z zeros before any non-zero are spaces, 9 zero prints '0' even if still not seen.
				outInt[i] = ' '
			} else {
				// For Z that is non-zero, or zero after nonZeroSeen, print digit
				// For 9 always print digit
				outInt[i] = rune(d)
				if d != '0' {
					// already set
				} else {
					// if ch == '9' and still not seen, this is the forced zero
					// For comma logic, should a forced zero count as seen for commas after?
					// There are no commas after final 9, so irrelevant.
				}
			}
			// After printing, if this digit was non-zero, nonZeroSeen true (already)
			// If digit is '0' and ch == '9', we still keep nonZeroSeen as before (could remain false)
			// But what about case where integer is 0 and we have Z's then 9 '0': commas before should be spaces (nonZeroSeen false) correct.
		} else {
			outInt[i] = ch
		}
	}
	// Edge: if the number is zero, the Z's are all spaces, 9 prints 0. Works.

	result := string(outInt)
	if dotPos >= 0 {
		result += "." + sFrac
	}
	// handle negative: if original negative, replace leading space with '-' ?
	// Not required for this program, but implement: find first non-space and put minus before it
	if neg {
		// find last leading space to place minus, or replace first space before digit
		rs := []rune(result)
		// locate first digit position
		for i := len(rs) - 1; i >= 0; i-- {
			if rs[i] >= '0' && rs[i] <= '9' {
				// find place to put minus: preceding char if space
				// simple: if there's a space immediately before first non-space digit run, put '-'
				break
			}
		}
		// simplistic: replace first space before number with '-'
		// find first non-space
		firstNonSpace := -1
		for i, c := range rs {
			if c != ' ' && c != ',' && c != '.' {
				firstNonSpace = i
				break
			}
		}
		if firstNonSpace > 0 && rs[firstNonSpace-1] == ' ' {
			rs[firstNonSpace-1] = '-'
		} else if firstNonSpace == 0 {
			// overflow, just prefix?
			result = "-" + result
			return result
		}
		result = string(rs)
	}
	// Ensure length equals len(picture)
	if len(result) != len(picture) {
		// pad/truncate (should not happen)
		if len(result) < len(picture) {
			result = strings.Repeat(" ", len(picture)-len(result)) + result
		} else {
			result = result[len(result)-len(picture):]
		}
	}
	return result
}

func formatCount(v int64) string {
	// PIC 9(5) zero-padded to 5
	mod := v % 100000
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%05d", mod)
}

// paragraphs

func READ_PARA() {
	if loanIndex >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanIndex]
	loanIndex++
	// pad to 21 with spaces if shorter
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	loanRec.LrAcct = line[0:6]
	loanRec.LrPrincipal = parseImplied(line[6:15], 2)
	loanRec.LrRate = parseImplied(line[15:19], 2)
	loanRec.LrYears = parseIntField(line[19:21])
}

