	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	// divide by 100 => Shift(-2)
	val := prod.Shift(-2)
	WsInterest = storeDecimal(val, 2, 9, true)

	// ADD WS-INTEREST TO WS-TOTAL
	sum := WsTotal.Add(WsInterest)
	WsTotal = storeDecimal(sum, 2, 11, false)

	// ADD 1 TO WS-COUNT
	WsCount++
	// store truncation for count field 9(5)
	if WsCount >= 100000 || WsCount < 0 {
		WsCount = WsCount % 100000
		if WsCount < 0 {
			WsCount += 100000
		}
	}

	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("RECORDS: %s\n", formatCount(WsCount))
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	// OPEN INPUT LOAN-FILE
	// Read file input.dat line sequential
	data, err := os.ReadFile("input.dat")
	if err != nil {
		// if file not found, treat as empty
		if os.IsNotExist(err) {
			loanLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		// Split by \n preserving lines
		raw := strings.ReplaceAll(string(data), "\r\n", "\n")
		// Use bufio approach to keep empty lines?
		// strings.Split
		parts := strings.Split(raw, "\n")
		// If file ends with newline, last element is "" after split; COBOL would not have extra record
		// We need to detect: if original ends with \n, the last split is extra empty which should be ignored
		// However an actual empty line (record of spaces) would be represented as "" line which after pad becomes spaces (a valid record)
		// Distinguishing is hard; but COBOL line sequential: each line is a record, final newline does not create extra record
		// So we drop last element if raw ends with "\n" and last element == ""
		if strings.HasSuffix(raw, "\n") && len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
		loanLines = parts
		// If file is empty, parts = [""] after split of "" -> we want [] ; handle
		if len(data) == 0 {
			loanLines = []string{}
		} else if len(loanLines) == 1 && loanLines[0] == "" && len(data) != 0 {
			// file contained just a newline? That is one empty record? The split handling above would have 1 element ""? Actually "\n" -> parts ["",""] -> after drop -> [""] => one empty record
			// keep as is
		}
		// Also need to handle alternative: use bufio.Scanner to avoid issues, but above is fine
		// To be safe, re-read with scanner for empty records handling? We'll keep lines as is
		// If file had no trailing newline, parts already correct
		// Need to ensure we treat lines that were empty (all spaces trimmed) as still a record: they are "" which will be padded
		_ = bufio.NewReader
	}

	WsEofFlag = "N"
	loanIndex = 0
	// PERFORM READ-PARA
	READ_PARA()
	// PERFORM PROCESS-PARA UNTIL INPUT-DONE
	for !isInputDone() {
		PROCESS_PARA()
