func tenPow(n int) decimal.Decimal {
	return decimal.NewFromInt(1).Shift(int32(n))
}

func storeDecimal(val decimal.Decimal, scale int32, intDigits int, doRound bool) decimal.Decimal {
	q := val
	if doRound {
		scaled := val.Shift(scale)
		var roundedScaled decimal.Decimal
		half := decimal.RequireFromString("0.5")
		if scaled.IsNegative() {
			roundedScaled = scaled.Sub(half).Ceil()
		} else {
			roundedScaled = scaled.Add(half).Floor()
		}
		q = roundedScaled.Shift(-scale)
	} else {
		q = val.Truncate(scale)
	}
	total := intDigits + int(scale)
	modBase := tenPow(total)
	scaled := q.Shift(scale)
	abs := scaled.Abs()
	if abs.Cmp(modBase) >= 0 {
		abs = abs.Mod(modBase)
		if scaled.IsNegative() {
			scaled = abs.Neg()
		} else {
			scaled = abs
		}
		q = scaled.Shift(-scale)
	}
	return q
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	scale := 0
	intPattern := picture
	if dotPos >= 0 {
		intPattern = picture[:dotPos]
		scale = len(picture) - dotPos - 1
	}
	intDigits := 0
	for _, ch := range intPattern {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	neg := val.IsNegative()
	if neg {
		val = val.Abs()
	}
	scaled := val.Shift(int32(scale)).Truncate(0)
	pow10 := tenPow(scale)
	intPart := scaled.Shift(-int32(scale)).Truncate(0)
	fIntDec := scaled.Sub(intPart.Mul(pow10))
	fracInt := fIntDec.IntPart()
	if fracInt < 0 {
		fracInt = -fracInt
	}
	intVal := intPart.IntPart()
	if intVal < 0 {
		intVal = -intVal
	}
	if intDigits > 0 {
		modBase := int64(1)
		for i := 0; i < intDigits; i++ {
			modBase *= 10
		}
		if modBase > 0 {
			intVal = intVal % modBase
		}
	}
	sInt := fmt.Sprintf("%0*d", intDigits, intVal)
	sFrac := ""
	if scale > 0 {
		sFrac = fmt.Sprintf("%0*d", scale, fracInt)
	}
	outInt := make([]rune, len(intPattern))
	digitIdx := 0
	nonZeroSeen := false
	for i, ch := range intPattern {
		if ch == ',' {
			if nonZeroSeen {
				outInt[i] = ','
			} else {
				outInt[i] = ' '
			}
		} else if ch == 'Z' || ch == '9' {
			d := sInt[digitIdx]
			digitIdx++
			if d != '0' {
				nonZeroSeen = true
			}
			if ch == 'Z' && d == '0' && !nonZeroSeen {
				outInt[i] = ' '
			} else {
				outInt[i] = rune(d)
			}
		} else {
			outInt[i] = ch
		}
	}
	result := string(outInt)
	if dotPos >= 0 {
		result += "." + sFrac
	}
	if neg {
		rs := []rune(result)
		firstNonSpace := -1
		for i, c := range rs {
			if c != ' ' && c != ',' && c != '.' {
				firstNonSpace = i
				break
			}
		}
		if firstNonSpace > 0 && rs[firstNonSpace-1] == ' ' {
			rs[firstNonSpace-1] = '-'
		} else if firstNonSpace == 0 {
			result = "-" + result
			return result
		}
		result = string(rs)
	}
	if len(result) != len(picture) {
		if len(result) < len(picture) {
			result = strings.Repeat(" ", len(picture)-len(result)) + result
		} else {
			result = result[len(result)-len(picture):]
		}
	}
	return result
}

func formatCount(v int64) string {
	mod := v % 100000
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%05d", mod)
}

func READ_PARA() {
	if loanIndex >= len(loanLines) {
		WsEofFlag = "Y"
		return
	}
	line := loanLines[loanIndex]
	loanIndex++
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	loanRec.LrAcct = line[0:6]
	loanRec.LrPrincipal = parseImplied(line[6:15], 2)
	loanRec.LrRate = parseImplied(line[15:19], 2)
	loanRec.LrYears = parseIntField(line[19:21])
}

func PROCESS_PARA() {
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	val := prod.Shift(-2)
	WsInterest = storeDecimal(val, 2, 9, true)
	sum := WsTotal.Add(WsInterest)
	WsTotal = storeDecimal(sum, 2, 11, false)
	WsCount++
	if WsCount >= 100000 || WsCount < 0 {
		WsCount = WsCount % 100000
		if WsCount < 0 {
			WsCount += 100000
		}
	}
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)
	READ_PARA()
}

func SUMMARY_PARA() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("RECORDS: %s\n", formatCount(WsCount))
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			loanLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		raw := strings.ReplaceAll(string(data), "\r\n", "\n")
		parts := strings.Split(raw, "\n")
		if strings.HasSuffix(raw, "\n") && len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
		loanLines = parts
		if len(data) == 0 {
			loanLines = []string{}
		}
	}
	WsEofFlag = "N"
	loanIndex = 0
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}
